-- Beauty Pulse · Nov Flashback brand cards: retail business model only (item_d business_model = 'retail'), by brand,
-- for the same LY / LLY cohort periods as sql/flashback.sql plus Sept 2024 / 2025 / 2026 (period 0). One run.
-- Output: d = "Y|p|days", r = "brand,gmv,units,mkd,np,gv,impressions;..." -> data/flashback_retail_raw.json
WITH dt0 AS (SELECT d, CASE WHEN d BETWEEN '2024-09-01' AND '2024-09-30' THEN STRUCT(2024 AS y, 0 AS p) WHEN d BETWEEN '2025-09-01' AND '2025-09-30' THEN STRUCT(2025 AS y, 0 AS p) WHEN d BETWEEN '2026-09-01' AND '2026-09-30' THEN STRUCT(2026 AS y, 0 AS p) WHEN d BETWEEN '2025-10-20' AND '2025-10-24' THEN STRUCT(2025 AS y, 1 AS p) WHEN d BETWEEN '2025-10-25' AND '2025-10-31' THEN STRUCT(2025 AS y, 2 AS p) WHEN d BETWEEN '2025-11-01' AND '2025-11-06' THEN STRUCT(2025 AS y, 3 AS p) WHEN d BETWEEN '2025-11-07' AND '2025-11-10' THEN STRUCT(2025 AS y, 4 AS p) WHEN d BETWEEN '2025-11-11' AND '2025-11-11' THEN STRUCT(2025 AS y, 5 AS p) WHEN d BETWEEN '2025-11-12' AND '2025-11-14' THEN STRUCT(2025 AS y, 6 AS p) WHEN d BETWEEN '2025-11-15' AND '2025-11-19' THEN STRUCT(2025 AS y, 7 AS p) WHEN d BETWEEN '2025-11-21' AND '2025-11-25' THEN STRUCT(2025 AS y, 8 AS p) WHEN d BETWEEN '2025-11-26' AND '2025-11-27' THEN STRUCT(2025 AS y, 9 AS p) WHEN d BETWEEN '2025-11-28' AND '2025-11-28' THEN STRUCT(2025 AS y, 10 AS p) WHEN d BETWEEN '2025-11-29' AND '2025-12-01' THEN STRUCT(2025 AS y, 11 AS p) WHEN d BETWEEN '2025-12-02' AND '2025-12-03' THEN STRUCT(2025 AS y, 12 AS p) WHEN d BETWEEN '2025-12-04' AND '2025-12-06' THEN STRUCT(2025 AS y, 13 AS p) WHEN d BETWEEN '2025-12-07' AND '2025-12-10' THEN STRUCT(2025 AS y, 14 AS p) WHEN d BETWEEN '2024-10-20' AND '2024-10-24' THEN STRUCT(2024 AS y, 1 AS p) WHEN d BETWEEN '2024-10-25' AND '2024-10-31' THEN STRUCT(2024 AS y, 2 AS p) WHEN d BETWEEN '2024-11-01' AND '2024-11-06' THEN STRUCT(2024 AS y, 3 AS p) WHEN d BETWEEN '2024-11-07' AND '2024-11-10' THEN STRUCT(2024 AS y, 4 AS p) WHEN d BETWEEN '2024-11-11' AND '2024-11-11' THEN STRUCT(2024 AS y, 5 AS p) WHEN d BETWEEN '2024-11-12' AND '2024-11-14' THEN STRUCT(2024 AS y, 6 AS p) WHEN d BETWEEN '2024-11-15' AND '2024-11-19' THEN STRUCT(2024 AS y, 7 AS p) WHEN d BETWEEN '2024-11-22' AND '2024-11-26' THEN STRUCT(2024 AS y, 8 AS p) WHEN d BETWEEN '2024-11-27' AND '2024-11-28' THEN STRUCT(2024 AS y, 9 AS p) WHEN d BETWEEN '2024-11-29' AND '2024-11-29' THEN STRUCT(2024 AS y, 10 AS p) WHEN d BETWEEN '2024-11-30' AND '2024-12-02' THEN STRUCT(2024 AS y, 11 AS p) WHEN d BETWEEN '2024-12-03' AND '2024-12-04' THEN STRUCT(2024 AS y, 12 AS p) WHEN d BETWEEN '2024-12-05' AND '2024-12-06' THEN STRUCT(2024 AS y, 13 AS p) WHEN d BETWEEN '2024-12-07' AND '2024-12-10' THEN STRUCT(2024 AS y, 14 AS p) END yp FROM UNNEST(ARRAY_CONCAT(GENERATE_DATE_ARRAY('2024-09-01','2024-12-10'), GENERATE_DATE_ARRAY('2025-09-01','2025-12-10'), GENERATE_DATE_ARRAY('2026-09-01','2026-09-30'))) d),
dt AS (SELECT d, yp.y, yp.p FROM dt0 WHERE yp IS NOT NULL),
nd AS (SELECT y, p, COUNT(*) days FROM dt GROUP BY 1, 2),
sk AS (SELECT sku, IFNULL(ANY_VALUE(brand_code), '(none)') brand FROM `noonbinamshi.custom_views.item_d`
  WHERE business_unit = 'beauty' AND IFNULL(inventory_type, '') <> 'samples & gwp' AND business_model = 'retail' GROUP BY 1),
cf AS (SELECT sku_config cfg, IFNULL(ANY_VALUE(brand_code), '(none)') brand FROM `noonbinamshi.custom_views.item_d`
  WHERE business_unit = 'beauty' AND IFNULL(inventory_type, '') <> 'samples & gwp' AND business_model = 'retail' GROUP BY 1),
s AS (SELECT dt.y, dt.p, sk.brand, SUM(x.gmv_inc_vat) gmv, SUM(x.items_gross) u, SUM(x.markdown_discount_value) mkd, SUM(x.normal_price_AED) np
  FROM `noonbinamshi.custom_views.sales_metrics` x JOIN sk USING (sku) JOIN dt ON dt.d = x.order_date_key
  WHERE (x.order_date_key BETWEEN '2024-09-01' AND '2024-12-10' OR x.order_date_key BETWEEN '2025-09-01' AND '2025-12-10' OR x.order_date_key BETWEEN '2026-09-01' AND '2026-09-30')
    AND x.marketplace IN ('namshi', 'namshi_v2') AND x.gmv_inc_vat > 0 GROUP BY 1, 2, 3),
t AS (SELECT dt.y, dt.p, cf.brand, SUM(o.glance_views) gv, SUM(o.search_impressions + o.non_search_impressions) im
  FROM `noonbinamshi.onsite_v1.onsite_measures` o JOIN cf ON cf.cfg = o.sku_config JOIN dt ON dt.d = o.date
  WHERE (o.date BETWEEN '2024-09-01' AND '2024-12-10' OR o.date BETWEEN '2025-09-01' AND '2025-12-10' OR o.date BETWEEN '2026-09-01' AND '2026-09-30') GROUP BY 1, 2, 3),
j AS (SELECT COALESCE(s.y, t.y) y, COALESCE(s.p, t.p) p, COALESCE(s.brand, t.brand) brand, IFNULL(s.gmv, 0) gmv, IFNULL(s.u, 0) u, IFNULL(s.mkd, 0) mkd, IFNULL(s.np, 0) np, IFNULL(t.gv, 0) gv, IFNULL(t.im, 0) im
  FROM s FULL JOIN t ON s.y = t.y AND s.p = t.p AND s.brand = t.brand)
SELECT FORMAT('%d|%d|%d', j.y, j.p, nd.days) d, STRING_AGG(FORMAT('%s,%.0f,%d,%.0f,%.0f,%d,%d', brand, gmv, u, mkd, np, gv, im), ';') r
FROM j JOIN nd USING (y, p) WHERE gmv > 0 OR im >= 5000 GROUP BY 1 ORDER BY 1
